import { Component } from '@angular/core';
import { Router } from '@angular/router';
import { Application } from 'src/app/auth/Models/Application';
import { Company } from 'src/app/landing/models/company';
import { Job } from 'src/app/landing/models/job';
import { ApplicationService } from 'src/app/service/application/application.service';
import { CompanyService } from 'src/app/service/company/company.service';
@Component({
  selector: 'app-company-profile',
  templateUrl: './company-profile.component.html',
  styleUrls: ['./company-profile.component.css'],
})
export class CompanyProfileComponent {

  ngOnInit() {
    console.log("ID:", localStorage.getItem("id"));
    console.log("Token:", localStorage.getItem("token"));

    this.getCompanyById();
    this.getJobsByCompany();
    this.getApplicantsByCompany();
    this.getPendingApplications();
    this.getHiredApplicants();
  }

    company!:Company;
    jobs:Job[] = [];
    applications:Application[] = [];
    pendingApplications :Application[] = [];
    approvedAppplications:Application[] = [];

    constructor(private compService:CompanyService , private appService:ApplicationService ,private router:Router){}

    getCompanyById(){
      this.compService.getCompanyById( Number(localStorage.getItem("id"))).subscribe(
        (res)=>
            this.company = res
      )
    }

    getJobsByCompany(){
      this.compService.getJobsByCompany(Number(localStorage.getItem("id"))).subscribe(
        (res)=>
            this.jobs = res
      )
    }

    getApplicantsByCompany(){
      this.appService.getApplicantsByCompany(Number(localStorage.getItem("id"))).subscribe(
        (res)=>
            this.applications = res
      )
    }

    getPendingApplications(){
      this.appService.getPendindApplicants(Number(localStorage.getItem("id"))).subscribe(
        (res)=>
            this.pendingApplications = res
      )
    }

    getHiredApplicants(){
      this.appService.getHiredApplicants(Number(localStorage.getItem("id"))).subscribe(
        (res)=>
            this.approvedAppplications = res
      )
    }

    logout(): void {
      localStorage.clear();
      this.router.navigate(['/']);
      alert("Continue to Logout?");
    }
}
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Company Profile · HireHub</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
  <link href="https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,500;9..144,600;9..144,700&family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap" rel="stylesheet">

</head>
<body>
<div class="page">
<header class="topnav app">
  <div class="wrap">
    <a routerLink="/" class="brand"><span class="brand-dot"></span>HireHub</a>
    <nav class="nav-links app-links">
      <a routerLink="/company-dashboard">Dashboard</a>
      <a routerLink="/company-post-job">Post a Job</a>
      <a routerLink="/company-manage-jobs">Manage Jobs</a>
      <a routerLink="/company-applicants">Applicants</a>
      <a routerLink="/profile-company"  class="active">Company Profile</a>
    </nav>
    <div style="display: flex; gap: 2rem;">
<div class="avatar" *ngIf="company?.companyName">
  {{ company.companyName.charAt(0) }}{{ company.companyName.split(' ')[1]?.charAt(0) || '' }}
</div>
<button class="btn btn-ghost-dark btn-sm" (click)="logout()">
        Logout
      </button> 
    </div>

</div>
</header>
<div class="app-shell">
<aside class="sidebar">
  <div class="sidebar-group">
    <span class="sidebar-label">General</span>
    <a routerLink="/company-dashboard" ><span class="dot"></span>Dashboard</a>
    <a routerLink="/profile-company" class="active"><span class="dot"></span>Company Profile</a>
  </div>
  <div class="sidebar-group">
    <span class="sidebar-label">Hiring</span>
    <a routerLink="/company-post-job"><span class="dot"></span>Post a Job</a>
    <a routerLink="/company-manage-jobs"><span class="dot"></span>Manage Jobs</a>
    <a routerLink="/company-applicants"><span class="dot"></span>Applicants</a>
  </div>
</aside>
<main class="main">

<div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:24px;">
  <div style="display:flex;gap:16px;align-items:center;">
    <div class="avatar" style="width:52px;height:52px;font-size:16px;"><div *ngIf="company?.companyName">
  {{ company.companyName.charAt(0) }}{{ company.companyName.split(' ')[1]?.charAt(0) || '' }}
</div></div>
    <div><h2 style="font-size:20px;">{{company.companyName}}</h2><p class="muted" style="font-size:13.5px;">{{company.location}}</p></div>
  </div>
  <a [routerLink]="['/company/edit',company.companyId]" class="btn btn-secondary btn-sm">Edit profile</a>
</div>
<div class="card" style="margin-bottom:16px;">
  <h3 style="font-size:14px;margin-bottom:8px;">Connect with us</h3>
  <p style="font-size:13.5px;">{{company.website}}</p>
</div>
<div class="card" style="margin-bottom:16px;">
  <h3 style="font-size:14px;margin-bottom:8px;">Description</h3>
  <p style="font-size:13.5px;">{{company.description}}</p>
</div>
<div class="card">
  <h3 style="font-size:14px;margin-bottom:8px;">Public preview</h3>
  <p class="muted" style="font-size:13px;margin-bottom:12px;">This is what job seekers see on your public company page.</p>
  <a routerLink="/company" class="btn btn-secondary">View public profile</a>
</div>

</main>
</div>
</div>
</body>
</html>
